import { Request, Response } from "express";
import { NotificationService } from "./notification.service";
import { SocketService } from "../socket/socket.service";
import { SOCKET_EVENTS } from "@syncra/validators";

export class NotificationController {

  /**
   * This endpoint is not used directly for creating notifications —
   * notifications are system-generated by other controllers (e.g. MessageController
   * on a mention). It is kept as a utility entry point if needed in future.
   */
  static list = async (req: Request, res: Response) => {
    try {
      const notifications = await NotificationService.list(req.user!.workspaceId!, req.user!.userId);
      res.status(200).json({ success: true, data: notifications });
    } catch (err: any) {
      res.status(400).json({ success: false, error: err.message });
    }
  };

  static markAsRead = async (req: Request, res: Response) => {
    try {
      const id = req.params.id as string;
      const notification = await NotificationService.markAsRead(req.user!.workspaceId!, req.user!.userId, id);
      res.status(200).json({ success: true, data: notification });
    } catch (err: any) {
      res.status(400).json({ success: false, error: err.message });
    }
  };

  static markAllAsRead = async (req: Request, res: Response) => {
    try {
      await NotificationService.markAllAsRead(req.user!.workspaceId!, req.user!.userId);
      res.status(200).json({ success: true, data: null });
    } catch (err: any) {
      res.status(400).json({ success: false, error: err.message });
    }
  };

  static delete = async (req: Request, res: Response) => {
    try {
      const id = req.params.id as string;
      await NotificationService.delete(req.user!.workspaceId!, req.user!.userId, id);
      res.status(200).json({ success: true, data: null });
    } catch (err: any) {
      res.status(400).json({ success: false, error: err.message });
    }
  };

  /**
   * Internal helper: creates a notification record and delivers it to the
   * target user via WebSocket in a single operation.
   * Called by other controllers (e.g. MessageController) — not a REST endpoint.
   */
  static async createAndDeliver(
    workspaceId: string,
    userId: string,
    payload: { type: string; title: string; body: string; link?: string }
  ) {
    const notification = await NotificationService.create(workspaceId, {
      userId,
      type: payload.type,
      title: payload.title,
      body: payload.body,
      link: payload.link,
    });

    // Deliver real-time toast to the target user's socket(s)
    SocketService.sendToUser(userId, SOCKET_EVENTS.NOTIFICATION_RECEIVED, notification);

    return notification;
  }
}

